"""Prepare OpenTwitter for an episode.

OpenTwitter serves ``GET /api/evaluation`` over the guest loopback.  The
recorded port is a property of the run rather than of the task, so the answering
port is discovered from the candidates the binding lists.  Preparation reads the
document and confirms the source posts the instruction quotes are present, that
the posts the task asks for have not been written yet, and that the episode's
account still exists.  It posts, replies, likes and follows nothing.
"""

from __future__ import annotations

import json
from typing import Any, Mapping

from evaluators.cua_review.core.initialization import InitializationError, MacAppInitializer

#: Port OpenTwitter serves on inside the guest.
DEFAULT_PORT = 4350


class OpenTwitterInitializer(MacAppInitializer):
    """Confirm the OpenTwitter starting point an episode assumes."""

    INITIALIZER_ID = "initializers.macos.opentwitter:OpenTwitterInitializer"
    APP_NAME = "OpenTwitter"
    BUNDLE_ID = "local.osomni.opentwitter"
    SETTLE_MS = 2500

    def verify_preconditions(self, controller: Any, params: Mapping[str, Any]) -> str:
        candidates = list(params.get("candidate_ports") or [DEFAULT_PORT])
        if params.get("port"):
            candidates.insert(0, params["port"])
        port, state, notes = self._read_loopback(
            controller, candidates, ["/api/evaluation"], what="OpenTwitter state"
        )
        if port is None:
            raise InitializationError(
                "OpenTwitter did not answer GET /api/evaluation"
                + (f" ({'; '.join(notes)})" if notes else "")
            )
        document = self._endpoint_body(state, "/api/evaluation")
        recorded = json.dumps(document, ensure_ascii=False)

        required = [str(phrase) for phrase in (params.get("required_phrases") or []) if str(phrase)]
        missing = [phrase for phrase in required if phrase not in recorded]
        if missing:
            raise InitializationError(
                "OpenTwitter does not carry the seeded source post(s) "
                + ", ".join(repr(phrase) for phrase in missing)
            )

        forbidden = [
            str(title) for title in (params.get("forbidden_target_posts") or []) if str(title)
        ]
        already = [title for title in forbidden if title in recorded]
        if already:
            raise InitializationError(
                "OpenTwitter already carries the target post(s) "
                + ", ".join(repr(title) for title in already)
            )

        account = str(params.get("expected_account_name") or "")
        if account and account not in recorded:
            raise InitializationError(f"OpenTwitter carries no {account} account")

        if dict(document.get("session") or {}).get("loggedIn"):
            raise InitializationError("OpenTwitter is already signed in")

        return (
            f"OpenTwitter answers on port {port} with {len(required)} seeded source post(s), "
            f"no target posts, and the {account or 'expected'} account present"
        )
